    view: ["value"],
    npc_dialogue: ["npc"],
    answer_submitted: ["value", "attempt", "correct"],
    hint_revealed: ["level"],
    puzzle_ended: ["result", "attempts_used"],
    rejected: ["attempted_action", "error"],
    end: ["outcome"],
